export const zDataPermission = z.enum([
    'DATA_RESTRICTED',
    'DATA_VIEW',
    'DATA_EXTEND',
    'DATA_UPDATE',
    'DATA_DELETE',
    'DATA_PERMISSIONS'
]);

/**
 * XML QName (prefix:localName)
 */
export const zQName = z.string().regex(/^[A-Za-z_][A-Za-z0-9._-]*:[A-Za-z_][A-Za-z0-9._-]*$/);

/**
 * Sort criterion for structured instance search POST bodies. String values use a QName or PROPVAL, CREATED, LASTMOD, optionally followed by |asc or |desc. Object values support property/prop, direction/dir and kind; at least one of property or prop must be provided by the client.
 *
 */
export const zSearchSortBy = z.union([
    z.string(),
    z.object({
        property: z.string().optional(),
        prop: z.string().optional(),
        direction: z.enum(['asc', 'desc']).optional().default('asc'),
        dir: z.enum(['asc', 'desc']).optional(),
        kind: z.enum([
            'auto',
            'value',
            'dating'
        ]).optional().default('auto')
    }).catchall(z.never())
]);

/**
 * Structured instance-search filter item. String items are logic operators. Object items either wrap a logic operator, describe a direct property comparison, or describe a one-hop linked-resource property comparison. `NOT_EXISTS` / `not_exists` checks that the target resource has no value for the given property; its `value` may be omitted and then defaults to `property`.
 *
 */
export const zSearchFilterItem = z.union([
    z.literal('AND'),
    z.literal('&&'),
    z.literal('OR'),
    z.literal('||'),
    z.literal('('),
    z.literal('LEFT'),
    z.literal('LEFT_'),
    z.literal(')'),
    z.literal('RIGHT'),
    z.literal('_RIGHT'),
    z.object({
        logic: z.enum([
            'AND',
            '&&',
            'OR',
            '||',
            '(',
            'LEFT',
            'LEFT_',
            ')',
            'RIGHT',
            '_RIGHT'
        ])
    }).catchall(z.never()),
    z.unknown().and(z.unknown()).and(z.object({
        linkProperty: zQName.optional(),
        linkProp: zQName.optional(),
        linkedClass: zQName.optional(),
        linkClass: zQName.optional(),
        property: zQName.optional(),
        prop: zQName.optional(),
        op: z.enum([
            'EQ',
            '==',
            'NE',
            '!=',
            'LT',
            '<',
            'LE',
            '<=',
            'GT',
            '>',
            'GE',
            '>=',
            'CONTAINS',
            'contains',
            'STRSTARTS',
            'strstarts',
            'STRENDS',
            'strends',
            'REGEXP',
            'regexp',
            'FULLTEXT',
            'fulltext',
            'OVERLAPS',
            'overlaps',
            'BEFORE',
            'before',
            'AFTER',
            'after',
            'NOT_EXISTS',
            'not_exists'
        ]),
        value: z.union([
            z.string(),
            z.number(),
            z.int(),
            z.boolean(),
            z.record(z.string(), z.unknown())
        ]).optional(),
        type: z.enum([
            'string',
            'langstring',
            'int',
            'integer',
            'decimal',
            'float',
            'double',
            'bool',
            'boolean',
            'iri',
            'qname',
            'date',
            'datetime',
            'dating'
        ]).optional(),
        lang: z.string().optional(),
        checkLinkedPermissions: z.boolean().optional().default(false)
    }).catchall(z.never())),
    z.intersection(z.unknown(), z.object({
        property: zQName.optional(),
        prop: zQName.optional(),
        op: z.enum([
            'EQ',
            '==',
            'NE',
            '!=',
            'LT',
            '<',
            'LE',
            '<=',
            'GT',
            '>',
            'GE',
            '>=',
            'CONTAINS',
            'contains',
            'STRSTARTS',
            'strstarts',
            'STRENDS',
            'strends',
            'REGEXP',
            'regexp',
            'FULLTEXT',
            'fulltext',
            'OVERLAPS',
            'overlaps',
            'BEFORE',
            'before',
            'AFTER',
            'after',
            'NOT_EXISTS',
            'not_exists'
        ]),
        value: z.union([
            z.string(),
            z.number(),
            z.int(),
            z.boolean(),
            z.record(z.string(), z.unknown())
        ]).optional(),
        type: z.enum([
            'string',
            'langstring',
            'int',
            'integer',
            'decimal',
            'float',
            'double',
            'bool',
            'boolean',
            'iri',
            'qname',
            'date',
            'datetime',
            'dating'
        ]).optional(),
        lang: z.string().optional()
    }).catchall(z.never()))
]);

/**
 * Mapping from QName role to data permission
 */
export const zHasRoleMap = z.record(z.string(), zDataPermission.nullable());

export const zUserAdditionalPropertyValue = z.union([
    z.string(),
    z.number(),
    z.number(),
    z.boolean(),
    z.array(z.union([
        z.string(),
        z.number(),
        z.number(),
        z.boolean()
    ]))
]);

/**
 * Mapping from user-class-specific property QName to scalar or array values.
 */
export const zUserAdditionalProperties = z.record(z.string(), zUserAdditionalPropertyValue);

/**
 * Map of role IRI/QName to permission value.
 */
export const zAttachedToRoleMap = z.record(z.string(), zDataPermission);

/**
 * One role IRI/QName or a list of role IRIs/QNames to remove from an instance permission map.
 */
export const zAttachedToRoleDelete = z.union([
    z.string(),
    z.array(z.string())
]);

/**
 * Update payload for `oldap:attachedToRole`. Clients may either send a full replacement map of role IRI/QName to DataPermission, or a patch object with `add` and/or `del`. `add` grants or changes permissions for the given roles; `del` removes role attachments from the instance.
 *
 */
export const zAttachedToRoleUpdate = z.union([
    zAttachedToRoleMap,
    z.object({
        add: zAttachedToRoleMap.optional(),
        del: zAttachedToRoleDelete.optional()
    }).catchall(z.never())
]);

/**
 * Lossless Dating response, requested with Accept: application/json; dating=structured. Prefer verbatimDate for display when present. Legacy clients retain string values.
 *
 */
export const zDatingValue = z.object({
    dateStart: z.array(z.int()).min(1).max(3),
    dateEnd: z.array(z.int()).min(1).max(3),
    datePrecision: z.string(),
    inCalendar: z.string(),
    iri: z.string().optional(),
    verbatimDate: z.string().optional(),
    before: z.array(z.string()).optional()
}).passthrough();

export const zValueArray = z.array(z.union([
    zDatingValue,
    z.string(),
    z.number(),
    z.number(),
    z.boolean(),
    z.null()
]));

export const zAnnotationRdfTerm = z.object({
    type: z.enum([
        'uri',
        'literal',
        'bnode'
    ]),
    value: z.string(),
    datatype: z.string().optional(),
    'xml:lang': z.string().optional()
}).catchall(z.never());

/**
 * Typed RDF term, or a scalar converted using the current field model
 */
export const zAnnotationInputValue = z.union([
    zAnnotationRdfTerm,
    z.string(),
    z.number(),
    z.boolean()
]);

export const zAnnotationFieldFilter = z.intersection(z.union([
    z.object({
        op: z.enum(['exists', 'not_exists']).optional()
    }).passthrough(),
    z.object({
        op: z.enum([
            'eq',
            'ne',
            'lt',
            'le',
            'gt',
            'ge'
        ]).optional()
    }).passthrough()
]), z.object({
    property: z.string(),
    op: z.enum([
        'eq',
        'ne',
        'lt',
        'le',
        'gt',
        'ge',
        'exists',
        'not_exists'
    ]),
    value: zAnnotationInputValue.optional()
}).catchall(z.never()));

export const zAnnotationFilter = z.object({
    property: z.string(),
    value: zAnnotationInputValue.optional(),
    exists: z.boolean().optional().default(true),
    fields: z.array(zAnnotationFieldFilter).optional()
}).catchall(z.never());

export const zAnnotationFields = z.record(z.string(), z.array(zAnnotationInputValue));

export const zAnnotationAdd = z.object({
    op: z.enum(['add']),
    property: z.string(),
    value: zAnnotationInputValue,
    fields: zAnnotationFields
}).catchall(z.never());

/**
 * Explicit edits committed with the parent instance; replace supplies the complete field set
 */
export const zAnnotationOperation = z.union([
    zAnnotationAdd,
    z.object({
        op: z.enum(['replace']),
        iri: z.string(),
        fields: zAnnotationFields
    }).catchall(z.never()),
    z.object({
        op: z.enum(['remove']),
        iri: z.string()
    }).catchall(z.never())
]);

export const zAssertionAnnotation = z.object({
    iri: z.string(),
    property: z.string(),
    value: zAnnotationRdfTerm,
    fields: z.record(z.string(), z.array(zAnnotationRdfTerm)),
    managed: z.boolean(),
    asserted: z.boolean()
}).passthrough();

/**
 * Create payload for an OLDAP resource instance. Project-specific properties are ontology-driven and therefore accepted as additional JSON properties. Instance permissions can be supplied as `attachedToRole` or `oldap:attachedToRole`, mapping role IRI/QName to DataPermission.
 *
 */
export const zInstanceCreateData = z.object({
    '@annotations': z.array(zAnnotationAdd).optional(),
    attachedToRole: zAttachedToRoleMap.optional(),
    'oldap:attachedToRole': zAttachedToRoleMap.optional()
}).catchall(z.unknown());

/**
 * Modify payload for an OLDAP resource instance. Project-specific properties are ontology-driven and therefore accepted as additional JSON properties. Normal properties can be replaced directly, deleted with `null`, or patched with property-specific `add`/`del` objects. `oldap:attachedToRole` uses a role-to-permission map or an `add`/`del` patch object.
 *
 */
export const zInstanceUpdateData = z.object({
    '@annotations': z.array(zAnnotationOperation).optional(),
    'oldap:attachedToRole': zAttachedToRoleUpdate.optional()
}).catchall(z.unknown());

/**
 * Payload for an atomic resource-class transformation that keeps the same IRI. `preserveClass` names the shared base class whose properties remain untouched. `targetClass` is the class asserted after the transformation. Target-specific ontology properties can be supplied under `properties` and/or `additionalProperties`. When `attachedToRole` is present, role attachments are replaced with the supplied role-to-DataPermission map. `linkFrom` can atomically add a shape-valid object-property link from another resource; the caller must have DATA_UPDATE on that resource at commit time.
 *
 */
export const zInstanceTransformData = z.object({
    targetClass: z.string(),
    preserveClass: z.string(),
    expectedSourceClass: z.string().optional(),
    properties: z.record(z.string(), z.unknown()).optional(),
    additionalProperties: z.record(z.string(), z.unknown()).optional(),
    attachedToRole: zAttachedToRoleMap.optional(),
    'oldap:attachedToRole': zAttachedToRoleMap.optional(),
    linkFrom: z.object({
        resourceIri: z.string(),
        property: z.string()
    }).catchall(z.never()).optional()
}).catchall(z.never());

/**
 * Move one `shared:ArchiveUnit`. Set `shared:parentArchiveUnit` to null to make the node a root. Omit `schema:position` to preserve its current value or send null to remove it.
 *
 */
export const zArchiveUnitMoveData = z.object({
    'shared:parentArchiveUnit': z.string().nullable(),
    'schema:position': z.int().nullish()
}).catchall(z.never());

/**
 * Move one user-managed `shared:StagingFolder` below a new parent.
 */
export const zStagingFolderMoveData = z.object({
    'shared:inStagingFolder': z.string()
}).catchall(z.never());

