export const zResourceSummaryResponse = z.object({
    resources: z.array(zResourceSummary)
}).catchall(z.never());

/**
 * Instance data as a property-value map. Known OLDAP system keys are modeled explicitly. Project-specific properties appear as additional keys with primitive values, arrays of primitive values, or permission maps.
 *
 */
export const zInstanceData = z.object({
    'rdf:type': z.array(z.string()).min(1).optional(),
    'virtual:inferredTypes': z.array(z.string()).min(1).optional(),
    'oldap:attachedToRole': zAttachedToRoleMap.optional(),
    'oldap:createdBy': z.array(z.url()).min(1),
    'oldap:lastModifiedBy': z.array(z.url()).min(1),
    'oldap:creationDate': z.array(z.iso.datetime({ offset: true })).min(1),
    'oldap:lastModificationDate': z.array(z.iso.datetime({ offset: true })).min(1)
}).catchall(z.union([
    zValueArray,
    zDatingValue,
    z.string(),
    z.number(),
    z.number(),
    z.boolean(),
    zAttachedToRoleMap
]).nullable());

